// ==UserScript==
// @name         Kraken
// @namespace    __KRAKEN_ORIGIN__
// @version      __KRAKEN_VERSION__
// @description  Kraken in the browser build of the game.
// @match        https://seafight.com/*
// @match        https://*.seafight.com/*
// @run-at       document-start
// @inject-into  content
// @grant        GM.xmlHttpRequest
// @grant        GM_xmlhttpRequest
// @connect      __KRAKEN_HOST__
// @updateURL    __KRAKEN_ORIGIN__/kraken.user.js
// @downloadURL  __KRAKEN_ORIGIN__/kraken.user.js
// ==/UserScript==

// Generated by `cargo xtask web` from web/userscript.template.js; the Worker
// fills in the site's origin when it serves /kraken.user.js.
//
// The bootstrap goes into the page itself (it has to wrap the page's own
// WebAssembly), straight away at document start. kraken-web is fetched here,
// through the userscript manager, only once the bootstrap asks for it in the
// frame that runs the game, and handed over with postMessage; that way the
// game's CSP and CORS rules never come into it.
(() => {
  "use strict";
  const ORIGIN = "__KRAKEN_ORIGIN__";
  const BOOT = __KRAKEN_BOOT__;

  function inject() {
    const script = document.createElement("script");
    script.textContent = `window.__KRAKEN_ASSETS_PENDING__ = true;\n${BOOT}`;
    (document.head || document.documentElement).appendChild(script);
    script.remove();
    if (document.documentElement.dataset.kraken !== "boot") {
      // A strict Content-Security-Policy on the page blocks inline scripts.
      console.warn("[kraken] the page blocked the bootstrap (CSP); Kraken cannot run here");
    }
  }

  // At the very start of a document there may be no <html> element yet.
  // The observer fires as soon as there is one, which is still before the
  // parser runs the page's first script.
  if (document.documentElement) {
    inject();
  } else {
    new MutationObserver((_, observer) => {
      if (!document.documentElement) return;
      observer.disconnect();
      inject();
    }).observe(document, { childList: true });
  }

  /* eslint-disable no-undef */
  const request =
    (typeof GM !== "undefined" && GM.xmlHttpRequest) ||
    (typeof GM_xmlhttpRequest !== "undefined" ? GM_xmlhttpRequest : null);
  /* eslint-enable no-undef */
  const get = (path, responseType) =>
    new Promise((resolve, reject) => {
      if (!request) return reject(new Error("the userscript manager offers no GM.xmlHttpRequest"));
      request({
        method: "GET",
        url: `${ORIGIN}/__kraken/${path}`,
        responseType,
        onload: (r) => (r.status === 200 ? resolve(r.response) : reject(new Error(`${path}: ${r.status}`))),
        onerror: () => reject(new Error(`${path}: network error`)),
      });
    });

  let assets = null;
  window.addEventListener("message", (event) => {
    if (event.source !== window || !event.data || !event.data.__krakenNeedAssets) return;
    assets =
      assets ||
      Promise.all([get("kraken_web.js", "text"), get("kraken_web_bg.wasm", "arraybuffer")]).then(([glue, wasm]) => ({
        glue,
        wasm,
      }));
    assets.then(
      (data) => window.postMessage({ __krakenAssets: data }, "*"),
      (error) => console.error("[kraken]", error),
    );
  });
})();
